const api = "https://onmyoji.fandom.com/api.php";
async function get(url) {
  try {
    const r = await fetch(url, { headers: { "User-Agent": "REA-style-research/1.0" } });
    const body = await r.text();
    return { status: r.status, len: body.length, head: body.slice(0, 2500) };
  } catch (e) { return { error: String(e) }; }
}
const [list, attrs, cats] = await Promise.all([
  get(api + "?action=parse&page=Shikigami%2FList&prop=wikitext&formatversion=2&format=json"),
  get(api + "?action=parse&page=Shikigami%2FAttributes&prop=wikitext&formatversion=2&format=json"),
  get(api + "?action=query&list=allcategories&aclimit=30&acprop=size&formatversion=2&format=json"),
]);
return { list, attrs, cats };

