// collect.mjs — scrape Onmyoji Wiki (Fandom/MediaWiki) content data into JSON.
// Sources: onmyoji.fandom.com (CC BY-NC-SA content). Images remain hosted by Fandom.
import fs from "node:fs/promises";
import path from "node:path";

const API = "https://onmyoji.fandom.com/api.php";
const HDR = { "User-Agent": "OnmyojiStyleSite/1.0 (personal data collection; contact via local project)" };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const OUT = path.resolve("data");
await fs.mkdir(OUT, { recursive: true });

async function wikitext(page) {
  const url = `${API}?action=parse&page=${encodeURIComponent(page)}&prop=wikitext&formatversion=2&format=json`;
  const r = await fetch(url, { headers: HDR });
  const j = await r.json();
  return j?.parse?.wikitext ?? "";
}

// ---- wikitext table parsing helpers ---------------------------------------
function maskPipes(s) {
  // protect pipes inside [[...]] and {{...}}
  return s
    .replace(/\[\[([^\]]*)\]\]/g, (m, g) => `[[${g.replace(/\|/g, "\u0001")}]])
    .replace(/\{\{([^{]*)\}\}/g, (m, g) => `{{${g.replace(/\|/g, "\u0002")}}}`);
}
function unmask(s) { return s.replace(/[\u0001\u0002]/g, "|"); }

function parseRows(text) {
  const mask = maskPipes(text);
  const chunks = mask.split("\n|-").slice(1);
  return chunks
    .map((chunk) =>
      chunk.replace(/\n\|(?!\|)/g, "\u0000").replace(/\|\|/g, "\u0000").split("\u0000"))
    .map((fields) => fields.map((f) => unmask(f.replace(/^\s*\|/, "")).trim()));
}

const linkTarget = (field) => {
  const m = field.match(/\[\[([^\]|\u0001]+?)\u0001?/);
  if (!m) return null;
  let t = unmask(m[1].trim());
  if (t.startsWith("File:") || t.startsWith("Category:")) return null;
  return t;
};
const fileRef = (field) => {
  const m = field.match(/\[\[File:([^\]|\u0001]+)/);
  return m ? m[1].trim() : null;
};

// ---- 1. Shikigami roster ---------------------------------------------------
const rosterRows = parseRows(await wikitext("Shikigami/List/All")).filter((r) => r.length >= 4);
const shikigami = rosterRows.map((f) => {
  const no = f[0].trim();
  const file = fileRef(f[1]);
  const en = linkTarget(f[2]) ?? "";
  let cn = "", jp = "", gl = "";
  if (f[2].includes("<br")) {
    const seg = f[2].split(/<br\s*\/?>/)[1]?.replace(/\[\[.*?\]\]/g, "").trim() ?? "";
    const parts = seg.split(/\s+-\s+/).filter(Boolean);
    cn = parts[0] ?? ""; jp = parts[1] ?? ""; gl = parts[2] ?? parts[1] ?? "";
  }
  const rar = f[3].match(/data-sort-values*=["']?([A-Z]+)["']?/) ?? f[3].match(/["']?([A-Z]+)["']?/);
  const rarity = f[3].match(/data-sort-value="([^"]+)"/)?.[1] ?? "";
  return {
    no: no === "-" ? null : parseInt(no) || null,
    en, cn, jp, gl: gl || en,
    rarity,
    image: file ? `File:${file}` : null,
    wiki: en ? `https://onmyoji.fandom.com/wiki/${encodeURIComponent(en.replace(/ /g, "_"))}` : null,
  };
}).filter((s) => s.en && s.rarity);

// ---- 2. Attributes (MIN / MAX tabs) ----------------------------------------
const attrText = await wikitext("Shikigami/Attributes");
const attrTabs = {};
const tabSplit = attrText.split(/\n\|-| /).slice(1);
// find tab positions
const tabPos = [...attrText.matchAll(/\|-| ([A-Z]+)=/g)];
const sections = [];
for (let i = 0; i < tabPos.length; i++) {
  const start = tabPos[i].index + tabPos[i][0].length;
  const end = i + 1 < tabPos.length ? tabPos[i + 1].index : attrText.length;
  sections.push({ tab: tabPos[i][1], text: attrText.slice(start, end) });
}
const statKey = ["atk", "hp", "def", "spd", "crit", "critdmg", "effhit", "effres"];
for (const sec of sections) {
  const rows = parseRows(sec.text).filter((r) => r.length >= 9).map((r) => {
    const no = r[0].match(/File:(\d+)/)?.[1];
    const en = linkTarget(r[0]) ?? null;
    const stats = {};
    statKey.forEach((k, i) => {
      let v = (r[i + 1] ?? "").replace(/%/g, "");
      const n = parseFloat(v);
      stats[k] = n;
    });
    return { no: no ? parseInt(no) : null, en, ...stats };
  }).filter((r) => r.no != null || r.en);
  if (rows.length) attrTabs[sec.tab.toLowerCase()] = rows;
}

// ---- 3. Souls --------------------------------------------------------------
const soulRows = parseRows(await wikitext("Soul/List/Released")).filter((r) => r.length >= 4);
const souls = soulRows.map((f) => {
  const en = linkTarget(f[2]) ?? "";
  let cn = "", jp = "";
  if (f[2].includes("<br")) {
    const seg = f[2].split(/<br\s*\/?>/)[1]?.replace(/\[\[.*?\]\]/g, "").trim() ?? "";
    const parts = seg.split(/\s+-\s+|(?<=[\u4e00-\u9fff])\s+(?=[A-Z])/).filter(Boolean);
    cn = parts[0] ?? ""; jp = parts[1] ?? "";
  }
  return {
    no: parseInt(f[0].trim()) || null,
    en, cn, jp,
    type: f[3].trim(),
    image: fileRef(f[1]) ? `File:${fileRef(f[1])}` : null,
    wiki: en ? `https://onmyoji.fandom.com/wiki/${encodeURIComponent(en.replace(/ /g, "_"))}` : null,
  };
}).filter((s) => s.en && /^\d+$/.test(String(s.no)));

// ---- 4. Infobox enrichment (per-shikigami details, batched) -----------------
const titles = shikigami.filter((s) => s.no != null).map((s) => s.en);
const details = {};
for (let i = 0; i < titles.length; i += 30) {
  const batch = titles.slice(i, i + 30);
  const url = `${API}?action=query&formatversion=2&prop=revisions&rvprop=content&rvslots=main&titles=${batch.map(encodeURIComponent).join("%7C")}`;
  const r = await fetch(url, { headers: HDR });
  const j = await r.json();
  for (const p of j.query?.pages ?? []) {
    const wt = p.revisions?.[0]?.slots?.main?.content;
    if (!wt) continue;
    const box = wt.match(/\{\{ShikigamiBox([\s\S]*?)\n\}\}/);
    if (!box) continue;
    const grab = (key) => {
      const m = box[1].match(new RegExp(`\\n\\|\\s*${key}\\s*=([^}]*?)(?=\\n\\||$)`, "s"));
      return m ? m[1].trim().replace(/<br\s*\/?>/g, " · ").replace(/\{\{[^}]*\}\}/g, "").replace(/\[\[([^]|]*)(\|([^]]*))?\]\]/g, "$1$3") : undefined;
    };
    details[p.title] = {
      cv: grab("cv"),
      intro: grab("intro")?.replace(/\s+/g, " "),
      release: grab("release")?.replace(/\s*\*\s*/g, "; "),
      method: grab("method")?.replace(/\s*\*\s*/g, "; "),
    };
  }
  await sleep(350);
}

// join details into shikigami
for (const s of shikigami) Object.assign(s, details[s.en] ?? {});

// ---- 5. Resolve image URLs --------------------------------------------------
function unique(list) { return [...new Set(list.filter(Boolean))]; }
const files = unique([
  ...shikigami.map((s) => s.image),
  ...souls.map((s) => s.image),
  "SSR.png", "SR.png", "R.png", "SP.png", "N.png",
]);
const fileUrls = {};
for (let i = 0; i < files.length; i += 50) {
  const batch = files.slice(i, i + 50).map((f) => `File:${f}`);
  const url = `${API}?action=query&formatversion=2&prop=imageinfo&iiprop=url&iiurlwidth=120&titles=${batch.map(encodeURIComponent).join("%7C")}`;
  const r = await fetch(url, { headers: HDR });
  const j = await r.json();
  for (const p of j.query?.pages ?? []) {
    const info = p.imageinfo?.[0];
    if (!info) continue;
    const key = p.title.replace(/^File:/, "");
    fileUrls[key] = { url: info.url, thumb: info.thumburl ?? info.url };
  }
  await sleep(300);
}
const shikNo = {};
for (const s of shikigami) if (s.image) { s.imageUrl = fileUrls[s.image.slice(5)]?.thumb ?? null; }
for (const s of souls) if (s.image) { s.imageUrl = fileUrls[s.image.slice(5)]?.thumb ?? null; }
const rarityIcons = {};
for (const r of ["SSR", "SR", "R", "SP", "N"]) rarityIcons[r] = fileUrls[r];
for (const s of shikigami) s.rarityIcon = rarityIcons[s.rarity] ?? null;

// ---- write ------------------------------------------------------------------
await fs.writeFile(path.join(OUT, "shikigami.json"), JSON.stringify(shikigami, null, 2));
await fs.writeFile(path.join(OUT, "souls.json"), JSON.stringify(souls, null, 2));
await fs.writeFile(path.join(OUT, "stats.json"), JSON.stringify(attrTabs, null, 2));

console.log(`shikigami: ${shikigami.length}`);
console.log(`souls: ${souls.length}`);
console.log(`details matched: ${Object.keys(details).length}`);
console.log(`stat tabs: ${Object.entries(attrTabs).map(([k, v]) => `${k}=${v.length}`).join(", ")}`);
console.log(`image urls resolved: ${Object.keys(fileUrls).length}/${files.length}`);
console.log(`rarity counts:`, JSON.stringify(shikigami.reduce((a, s) => (a[s.rarity] = (a[s.rarity] ?? 0) + 1, a), {})));

