/* ============================================================
   Onmyoji Codex — design system
   Palette & typography are an original Heian-game-inspired theme
   (night indigo + vermillion seal + gold), informed by the mood
   of the Onmyoji Wiki but not copied from it.
   ============================================================ */
:root {
  --bg: #0f0a13;
  --bg-soft: #161020;
  --surface: #1c1427;
  --surface-2: #241a30;
  --border: #3b2b4d;
  --border-soft: #2b2039;
  --text: #ede6dc;
  --muted: #a89d92;
  --faint: #7d7280;

  --vermillion: #b03027;
  --vermillion-hi: #d95546;
  --gold: #c9a227;
  --gold-soft: #e5cf7a;

  --sp: #e0554c;
  --ssr: #d4af37;
  --sr: #9b6fd4;
  --r: #5d9fd4;
  --n: #8b8b8f;

  --radius: 10px;
  --radius-sm: 6px;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  --font-serif: "Zen Old Mincho", "Noto Serif JP", "Yu Mincho", serif;
  --font-latin: "Cormorant Garamond", "Zen Old Mincho", serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background:
    radial-gradient(1200px 600px at 85% -10%, rgba(176, 48, 39, 0.10), transparent 60%),
    radial-gradient(900px 500px at -10% 20%, rgba(201, 162, 39, 0.06), transparent 55%),
    var(--bg);
  color: var(--text);
  font-family: var(--font-serif);
  line-height: 1.6;
  min-height: 100vh;
}

::selection { background: rgba(217, 85, 70, 0.4); }

/* ---------- Scrollbar ---------- */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 6px; }
::-webkit-scrollbar-thumb:hover { background: #4d3a63; }

/* ---------- Navigation ---------- */
.nav {
  position: sticky;
  top: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 0.8rem clamp(1rem, 4vw, 3rem);
  background: rgba(15, 10, 19, 0.82);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-soft);
}
.nav .brand {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  text-decoration: none;
  color: var(--text);
  font-size: 1.15rem;
  letter-spacing: 0.12em;
}
.seal {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--vermillion), #7d1f18);
  color: #f6e9d8;
  border-radius: 7px;
  font-size: 1.05rem;
  font-weight: 700;
  box-shadow: 0 2px 10px rgba(176, 48, 39, 0.45);
  font-family: var(--font-serif);
}
.nav .brand small {
  display: block;
  color: var(--muted);
  font-size: 0.68rem;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  font-family: var(--font-serif);
}
.nav nav { margin-left: auto; display: flex; gap: 1.4rem; }
.nav nav a {
  color: var(--muted);
  text-decoration: none;
  font-size: 0.95rem;
  letter-spacing: 0.08em;
  padding: 0.3rem 0;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.nav nav a:hover, .nav nav a.active { color: var(--gold-soft); border-color: var(--vermillion); }

/* ---------- Layout ---------- */
.wrap { max-width: 1240px; margin: 0 auto; padding: 0 clamp(1rem, 4vw, 3rem); }
.section { padding: 3.5rem 0; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding: 6rem 0 4rem;
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(700px 380px at 70% 30%, rgba(176, 48, 39, 0.16), transparent 65%);
  pointer-events: none;
}
.hero-inner { position: relative; display: grid; grid-template-columns: auto 1fr; gap: 2.5rem; align-items: center; }
.hero-mono {
  writing-mode: vertical-rl;
  font-size: clamp(1.6rem, 3.4vw, 2.6rem);
  letter-spacing: 0.55em;
  color: var(--gold-soft);
  border-left: 2px solid rgba(201, 162, 39, 0.35);
  border-right: 2px solid rgba(201, 162, 39, 0.35);
  padding: 1.2rem 0.7rem;
  text-shadow: 0 0 24px rgba(233, 207, 122, 0.25);
}
.hero h1 {
  margin: 0 0 0.4rem;
  font-size: clamp(2.1rem, 5vw, 3.4rem);
  font-weight: 700;
  letter-spacing: 0.06em;
  font-family: var(--font-latin);
}
.hero h1 .accent { color: var(--vermillion-hi); }
.hero .sub {
  color: var(--muted);
  max-width: 60ch;
  margin-bottom: 1.6rem;
  font-size: 1.05rem;
}
.hero .cta { display: flex; gap: 1rem; flex-wrap: wrap; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.62rem 1.4rem;
  border-radius: var(--radius-sm);
  font-family: var(--font-serif);
  font-size: 0.95rem;
  letter-spacing: 0.1em;
  text-decoration: none;
  cursor: pointer;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  transition: all 0.2s;
}
.btn.primary {
  background: linear-gradient(135deg, var(--vermillion), #8a241c);
  border-color: transparent;
  color: #f9ecdd;
  box-shadow: 0 4px 18px rgba(176, 48, 39, 0.4);
}
.btn.primary:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(217, 85, 70, 0.45); }
.btn.ghost:hover { border-color: var(--gold); color: var(--gold-soft); }

/* ---------- Stat band ---------- */
.stats-band {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 1rem;
}
.stat-card {
  background: linear-gradient(160deg, var(--surface), var(--bg-soft));
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 1.1rem 1.3rem;
  position: relative;
  overflow: hidden;
}
.stat-card::after {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 3px;
  background: linear-gradient(90deg, var(--vermillion), transparent 70%);
}
.stat-card .num { font-size: 2rem; font-family: var(--font-latin); color: var(--gold-soft); line-height: 1.1; }
.stat-card .label { color: var(--muted); font-size: 0.85rem; letter-spacing: 0.14em; text-transform: uppercase; }
.stat-card .mini { margin-top: 0.55rem; display: flex; gap: 0.55rem; font-size: 0.78rem; color: var(--faint); }
.stat-card .mini b { color: var(--text); font-weight: 600; }

/* ---------- Section headings ---------- */
.sec-head { display: flex; align-items: baseline; gap: 1rem; margin-bottom: 1.6rem; }
.sec-head h2 { margin: 0; font-family: var(--font-latin); font-size: 1.7rem; letter-spacing: 0.1em; }
.sec-head .jp { color: var(--vermillion-hi); font-size: 1.15rem; }
.sec-head .spacer { flex: 1; border-bottom: 1px solid var(--border-soft); }
.sec-head a { color: var(--muted); font-size: 0.85rem; text-decoration: none; letter-spacing: 0.1em; }
.sec-head a:hover { color: var(--gold-soft); }

/* ---------- Cards grid ---------- */
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 14px; }
.card {
  position: relative;
  background: linear-gradient(165deg, var(--surface-2), var(--surface));
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 10px 10px 14px;
  cursor: pointer;
  text-align: center;
  transition: transform 0.18s ease, border-color 0.18s, box-shadow 0.18s;
  overflow: hidden;
}
.card:hover {
  transform: translateY(-4px);
  border-color: var(--border);
  box-shadow: var(--shadow);
}
.card img {
  width: 100%;
  aspect-ratio: 1;
  object-fit: contain;
  border-radius: var(--radius-sm);
  background:
    radial-gradient(120px 90px at 50% 45%, rgba(201, 162, 39, 0.08), transparent 75%);
  image-rendering: auto;
}
.card .name { margin-top: 8px; font-size: 0.9rem; line-height: 1.35; letter-spacing: 0.04em; }
.card .cn { color: var(--muted); font-size: 0.75rem; }
.card .meta { display: flex; justify-content: center; gap: 6px; margin-top: 6px; align-items: center; }
.card .no { color: var(--faint); font-size: 0.7rem; font-family: var(--font-latin); }

/* rarity styling */
.card[data-rarity="SSR"] { border-color: rgba(212, 175, 55, 0.35); }
.card[data-rarity="SP"]  { border-color: rgba(224, 85, 76, 0.4); }
.card[data-rarity="SR"]  { border-color: rgba(155, 111, 212, 0.35); }
.card[data-rarity="R"]   { border-color: rgba(93, 159, 212, 0.3); }
.card[data-rarity="N"]   { opacity: 0.9; }

.badge {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  padding: 2px 8px;
  border-radius: 20px;
  border: 1px solid;
  text-transform: uppercase;
  font-family: var(--font-serif);
}
.badge.SSR { color: var(--ssr); border-color: rgba(212, 175, 55, 0.5); background: rgba(212, 175, 55, 0.08); }
.badge.SR  { color: var(--sr);  border-color: rgba(155, 111, 212, 0.5); background: rgba(155, 111, 212, 0.08); }
.badge.R   { color: var(--r);   border-color: rgba(93, 159, 212, 0.5);  background: rgba(93, 159, 212, 0.08); }
.badge.SP  { color: var(--sp);  border-color: rgba(224, 85, 76, 0.55);  background: rgba(224, 85, 76, 0.1); }
.badge.N   { color: var(--n);   border-color: rgba(139, 139, 143, 0.4); background: rgba(139, 139, 143, 0.08); }

/* ---------- Toolbar ---------- */
.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  align-items: center;
  margin-bottom: 1.6rem;
  position: sticky;
  top: 58px;
  z-index: 40;
  background: rgba(15, 10, 19, 0.7);
  backdrop-filter: blur(8px);
  padding: 0.8rem 0;
  border-bottom: 1px solid var(--border-soft);
}
.search {
  flex: 1 1 240px;
  max-width: 380px;
  position: relative;
}
.search input {
  width: 100%;
  padding: 0.55rem 0.9rem 0.55rem 2.2rem;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: var(--radius-sm);
  font-family: var(--font-serif);
  font-size: 0.95rem;
  outline: none;
  transition: border-color 0.2s;
}
.search input:focus { border-color: var(--gold); }
.search::before {
  content: "⌕";
  position: absolute;
  left: 0.7rem;
  top: 50%;
  transform: translateY(-54%);
  color: var(--muted);
  font-size: 1.1rem;
}
.chips { display: flex; gap: 0.5rem; flex-wrap: wrap; }
.chip {
  padding: 0.35rem 0.95rem;
  border-radius: 20px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-family: var(--font-serif);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  transition: all 0.18s;
}
.chip:hover { color: var(--text); border-color: var(--faint); }
.chip.on.SSR, .chip.on { color: #f3e6cc; background: linear-gradient(135deg, var(--vermillion), #8a241c); border-color: transparent; }

select.sort {
  padding: 0.5rem 0.8rem;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: var(--radius-sm);
  font-family: var(--font-serif);
}
.count-note { color: var(--faint); font-size: 0.8rem; margin-left: auto; letter-spacing: 0.08em; }

/* ---------- Souls list ---------- */
.soul-row {
  display: grid;
  grid-template-columns: 52px 1fr auto;
  gap: 1rem;
  align-items: center;
  padding: 0.7rem 1rem;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: linear-gradient(160deg, var(--surface-2), var(--surface));
  transition: border-color 0.15s, transform 0.15s;
}
.soul-row:hover { border-color: var(--border); transform: translateX(3px); }
.soul-row img { width: 46px; height: 46px; object-fit: contain; }
.soul-row .names { display: flex; flex-direction: column; }
.soul-row .en { font-size: 1rem; letter-spacing: 0.05em; }
.soul-row .cn { color: var(--muted); font-size: 0.78rem; }
.soul-row a { color: inherit; text-decoration: none; }
.soul-list { display: flex; flex-direction: column; gap: 8px; }

/* type table (souls) */
.type-col { min-width: 72px; text-align: center; }

/* ---------- Modal ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(8, 5, 10, 0.72);
  backdrop-filter: blur(6px);
  display: none;
  place-items: center;
  z-index: 100;
  padding: 1.2rem;
}
.modal-backdrop.open { display: grid; }
.modal {
  width: min(760px, 94vw);
  max-height: 88vh;
  overflow-y: auto;
  background: linear-gradient(170deg, var(--surface-2), var(--bg-soft));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.8rem 2rem;
  position: relative;
}
.modal::before {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 4px;
  background: linear-gradient(90deg, var(--vermillion), var(--gold) 50%, transparent);
}
.modal .close {
  position: absolute;
  top: 0.8rem; right: 1rem;
  background: none;
  border: none;
  color: var(--muted);
  font-size: 1.5rem;
  cursor: pointer;
  transition: color 0.2s;
}
.modal .close:hover { color: var(--vermillion-hi); }
.md-head { display: flex; gap: 1.4rem; align-items: flex-start; }
.md-head img.avatar {
  width: 132px; height: 132px;
  object-fit: contain;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: radial-gradient(100px 80px at 50% 45%, rgba(201, 162, 39, 0.1), transparent 75%);
}
.md-head h3 { margin: 0 0 0.2rem; font-family: var(--font-latin); font-size: 1.55rem; letter-spacing: 0.05em; }
.md-names { color: var(--muted); font-size: 0.88rem; margin-bottom: 0.4rem; }
.md-meta { display: flex; gap: 0.6rem; flex-wrap: wrap; align-items: center; margin-top: 0.4rem; }
.md section { margin-top: 1.2rem; }
.md h4 {
  margin: 0 0 0.5rem;
  color: var(--gold-soft);
  font-size: 0.85rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-family: var(--font-serif);
}
.md p { margin: 0; color: #cfc5ba; font-size: 0.93rem; }
table.mini {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
  font-family: var(--font-latin);
}
table.mini th, table.mini td {
  padding: 6px 10px;
  border: 1px solid var(--border-soft);
  text-align: center;
}
table.mini th { background: rgba(176, 48, 39, 0.16); color: #e8ddca; letter-spacing: 0.1em; font-weight: 600; }
table.mini td { color: #cbc0b5; }
table.mini tr td:first-child, table.mini tr th:first-child { text-align: left; letter-spacing: normal; font-family: var(--font-serif); }
.md .link-out { margin-top: 1.4rem; }

/* ---------- Footer ---------- */
footer {
  margin-top: 4rem;
  border-top: 1px solid var(--border-soft);
  padding: 2.2rem 0 3rem;
  color: var(--faint);
  font-size: 0.85rem;
}
footer .wrap { display: flex; flex-direction: column; gap: 0.5rem; }
footer a { color: var(--muted); }
footer a:hover { color: var(--gold-soft); }

/* ---------- Utilities ---------- */
.skeleton {
  height: 210px;
  border-radius: var(--radius);
  background: linear-gradient(100deg, var(--surface) 30%, var(--surface-2) 50%, var(--surface) 70%);
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite;
}
@keyframes shimmer { to { background-position: -200% 0; } }
.center-note { text-align: center; color: var(--muted); padding: 3rem 0; }

@media (max-width: 720px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-mono { writing-mode: horizontal-tb; border: none; padding: 0; letter-spacing: 0.3em; }
  .md-head { flex-direction: column; align-items: center; text-align: center; }
  .toolbar .count-note { display: none; }
}

/* app.js — shared data loader + page renderers.
   Data: data/*.json produced by tools/collect.mjs (Onmyoji Wiki, CC BY-NC-SA). */

const state = { shikigami: [], souls: [], stats: { min: [], max: [] } };

const RARITY_ORDER = { SP: 0, SSR: 1, SR: 2, R: 3, N: 4 };
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

async function loadAll() {
  const base = document.body.dataset.data ?? "data/";
  const [sh, so, st] = await Promise.all([
    fetch(base + "shikigami.json").then((r) => r.json()),
    fetch(base + "souls.json").then((r) => r.json()),
    fetch(base + "stats.json").then((r) => r.json()),
  ]);
  state.shikigami = sh;
  state.souls = so.sort((a, b) => a.no - b.no);
  state.stats = st;
  document.dispatchEvent(new CustomEvent("data-ready"));
}

const statMap = (tab) => Object.fromEntries(state.stats[tab].map((r) => [r.no, r]));

/* ============ index.html ============ */
async function renderIndex() {
  await loadAll();
  const counts = {};
  for (const s of state.shikigami) counts[s.rarity] = (counts[s.rarity] ?? 0) + 1;

  const byNo = Object.fromEntries(state.shikigami.filter((s) => s.no != null).map((s) => [s.no, s]));
  const band = document.getElementById("stats-band");
  if (band) {
    band.innerHTML = `
      <div class="stat-card"><div class="num">${state.shikigami.length}</div><div class="label">Shikigami</div>
        <div class="mini"><span><b>${counts.SSR ?? 0}</b> SSR</span><span><b>${counts.SR ?? 0}</b> SR</span><span><b>${counts.SP ?? 0}</b> SP</span></div></div>
      <div class="stat-card"><div class="num">${state.souls.length}</div><div class="label">Soul Sets</div>
        <div class="mini"><span>types: ATK / DEF / HP / Crit</span></div></div>
      <div class="stat-card"><div class="num">${state.stats.max.length}</div><div class="label">Stat Records</div>
        <div class="mini"><span>min &amp; max, 8 attributes</span></div></div>
      <div class="stat-card"><div class="num">${state.shikigami.filter((s) => s.cv).length}</div><div class="label">Voice Actors</div>
        <div class="mini"><span>credited on the wiki</span></div></div>`;
  }

  // featured: first few unlocked SSR/SP by highest number
  const featured = state.shikigami
    .filter((s) => (s.rarity === "SSR" || s.rarity === "SP") && s.imageUrl && s.no)
    .sort((a, b) => b.no - a.no)
    .slice(0, 8);
  const feat = document.getElementById("featured");
  if (feat) {
    feat.classList.add("grid");
    feat.innerHTML = featured.map((s) => shikCard(s)).join("");
    feat.querySelectorAll(".card").forEach((el) =>
      el.addEventListener("click", () => openModal(byNo[el.dataset.no])));
  }
}

/* ============ shikigami.html ============ */
let currentQuery = "";
let currentRar = "ALL";
let currentSort = "no-desc";

function shikCard(s) {
  return `
  <div class="card" data-no="${s.no}" data-rarity="${s.rarity}" tabindex="0" role="button"
       aria-label="${esc(s.en)} (${s.rarity})">
    ${s.imageUrl ? `<img src="${s.imageUrl}" loading="lazy" alt="${esc(s.en)}">` : `<div class="skeleton"></div>`}
    <div class="name"><strong>${esc(s.en)}</strong>${s.cn ? `<div class="cn">${esc(s.cn)}</div>` : ""}</div>
    <div class="meta"><span class="badge ${s.rarity}">${s.rarity}</span>${s.no ? `<span class="no">No.${s.no}</span>` : ""}</div>
  </div>`;
}

function renderGrid() {
  const grid = document.getElementById("shik-grid");
  const note = document.getElementById("count-note");
  let list = state.shikigami.filter((s) => currentRar === "ALL" || s.rarity === currentRar);
  if (currentQuery.trim()) {
    const q = currentQuery.trim().toLowerCase();
    list = list.filter((s) => [s.en, s.cn, s.jp, s.gl, s.cv].some((v) => v && v.toLowerCase().includes(q)));
  }
  const cmp = {
    "no-desc": (a, b) => (b.no ?? 1e9) - (a.no ?? 1e9),
    "no-asc": (a, b) => (a.no ?? 1e9) - (b.no ?? 1e9),
    "rar": (a, b) => RARITY_ORDER[a.rarity] - RARITY_ORDER[b.rarity] || (b.no ?? 0) - (a.no ?? 0),
    "en": (a, b) => a.en.localeCompare(b.en),
  }[currentSort];
  list = [...list].sort(cmp);
  note.textContent = `${list.length} / ${state.shikigami.length} shown`;
  grid.innerHTML = list.length
    ? list.map(shikCard).join("")
    : `<div class="center-note" style="grid-column:1/-1">No shikigami match your search.</div>`;
  grid.querySelectorAll(".card").forEach((el) => el.addEventListener("click", () => openModal(list.find((x) => String(x.no) === el.dataset.no))));
}

async function renderShikigami() {
  await loadAll();
  const grid = document.getElementById("shik-grid");
  grid.innerHTML = Array.from({ length: 12 }, () => `<div class="skeleton"></div>`).join("");

  document.getElementById("search").addEventListener("input", (e) => { currentQuery = e.target.value; renderGrid(); });
  document.querySelectorAll(".chip[data-rarity]").forEach((chip) =>
    chip.addEventListener("click", () => {
      document.querySelectorAll(".chip").forEach((c) => c.classList.remove("on"));
      chip.classList.add("on");
      currentRar = chip.dataset.rarity;
      renderGrid();
    }));
  document.getElementById("sort").addEventListener("change", (e) => { currentSort = e.target.value; renderGrid(); });
  document.getElementById("sort").value = currentSort;

  // auto "ALL" chip active by default
  const allChip = document.querySelector('.chip[data-rarity="ALL"]');
  if (allChip) allChip.classList.add("on");
  renderGrid();
}

/* ============ souls.html ============ */
let soulQuery = "";
let soulType = "ALL";

async function renderSouls() {
  await loadAll();
  const types = ["ALL", ...[...new Set(state.souls.map((s) => s.type))].filter(Boolean).sort()];
  const chips = document.getElementById("type-chips");
  chips.innerHTML = types.map((t) => `<button class="chip${t === "ALL" ? " on" : ""}" data-type="${t}">${t}</button>`).join("");
  chips.querySelectorAll(".chip").forEach((chip) =>
    chip.addEventListener("click", () => {
      chips.querySelectorAll(".chip").forEach((c) => c.classList.remove("on"));
      chip.classList.add("on");
      soulType = chip.dataset.type;
      renderSoulList();
    }));
  document.getElementById("soul-search").addEventListener("input", (e) => { soulQuery = e.target.value; renderSoulList(); });
  renderSoulList();
}

function renderSoulList() {
  const listEl = document.getElementById("soul-list");
  const note = document.getElementById("count-note");
  let list = state.souls;
  if (soulType !== "ALL") list = list.filter((s) => s.type === soulType);
  if (soulQuery.trim()) {
    const q = soulQuery.trim().toLowerCase();
    list = list.filter((s) => [s.en, s.cn, s.jp].some((v) => v && v.toLowerCase().includes(q)));
  }
  note.textContent = `${list.length} / ${state.souls.length} shown`;
  listEl.innerHTML = list.length ? list.map((s) => `
    <a class="soul-row" href="${s.wiki}" target="_blank" rel="noopener">
      <span>${s.imageUrl ? `<img src="${s.imageUrl}" loading="lazy" alt="${esc(s.en)} icon">` : ""}</span>
      <span class="names">
        <span class="en"><strong>No.${s.no}</strong> · ${esc(s.en)}</span>
        <span class="cn">${esc(s.cn)}${s.jp ? ` — ${esc(s.jp)}` : ""}</span>
      </span>
      <span class="type-col"><span class="badge ${s.type}">${esc(s.type)}</span></span>
    </a>`).join("")
    : `<div class="center-note">No souls match your search.</div>`;
}

/* ============ Modal (shikigami detail) ============ */
function openModal(s) {
  if (!s) return;
  const bd = document.getElementById("modal-backdrop");
  const min = statMap("min")[s.no] ?? {};
  const max = statMap("max")[s.no] ?? {};
  const statRows = ["atk", "hp", "def", "spd", "crit", "critdmg", "effhit", "effres"];
  const labels = { atk: "ATK", hp: "HP", def: "DEF", spd: "SPD", crit: "Crit", critdmg: "Crit DMG", effhit: "Eff Hit %", effres: "Eff Res %" };
  const pct = new Set(["crit", "critdmg", "effhit", "effres"]);
  const statTable = statRows.some((k) => min[k] != null)
    ? `<section><h4>Base Stats</h4>
       <table class="mini"><thead><tr><th></th>${statRows.map((k) => `<th>${labels[k]}</th>`).join("")}</tr></thead>
       <tbody>
         <tr><td>LV1</td>${statRows.map((k) => `<td>${min[k] ?? "?"}${pct.has(k) || String(min[k])?.endsWith("") ? "" : ""}</td>`).join("")}</tr>
         <tr><td>MAX</td>${statRows.map((k) => `<td>${max[k] ?? "?"}</td>`).join("")}</tr>
       </tbody></table></section>`
    : "";

  bd.querySelector(".modal").innerHTML = `
    <button class="close" aria-label="Close">✕</button>
    <div class="md">
      <div class="md-head">
        <img class="avatar" src="${s.imageUrl ?? ""}" alt="${esc(s.en)}">
        <div>
          <h3>${esc(s.en)}</h3>
          <div class="md-names">${esc(s.cn)}${s.jp ? ` · ${esc(s.jp)}` : ""}${s.gl && s.gl !== s.en ? ` · ${esc(s.gl)}` : ""}</div>
          <div class="md-meta">
            <span class="badge ${s.rarity}">${s.rarity}</span>
            ${s.no ? `<span class="no" style="color:var(--faint);font-size:.78rem;">No.${s.no}</span>` : ""}
            ${s.cv ? `<span style="color:var(--muted);font-size:.82rem;">CV: ${esc(s.cv)}</span>` : ""}
          </div>
        </div>
      </div>
      ${s.intro ? `<section><h4>Introduction</h4><p>${esc(s.intro)}</p></section>` : ""}
      ${s.method ? `<section><h4>How to Obtain</h4><p>${esc(s.method)}</p></section>` : ""}
      ${statTable}
      <section class="link-out">
        <a class="btn ghost" href="${s.wiki}" target="_blank" rel="noopener">View on Onmyoji Wiki ↗</a>
      </section>
    </div>`;
  bd.querySelector(".close").addEventListener("click", () => bd.classList.remove("open"));
  bd.addEventListener("click", (e) => { if (e.target === bd) bd.classList.remove("open"); }, { once: true });
  bd.classList.add("open");
}

document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") document.getElementById("modal-backdrop")?.classList.remove("open");
});

/* boot by page */
const page = document.body.dataset.page;
window.addEventListener("DOMContentLoaded", () => {
  if (page === "index") renderIndex();
  else if (page === "shikigami") renderShikigami();
  else if (page === "souls") renderSouls();
});

