// What does the API say, and do alternate names exist?
const api = "https://onmyoji.fandom.com/api.php";
async function imagesOf(titles) {
  const url = `${api}?action=query&format=json&formatversion=2&prop=imageinfo&iiprop=url&titles=${titles.map(encodeURIComponent).join("%7C")}`;
  const j = await (await fetch(url)).json();
  return j.query?.pages.map(p => ({ title: p.title, url: p.imageinfo?.[0]?.url ?? null, missing: p.missing ?? false }));
}
const info = await imagesOf(["File:604.png", "File:604.jpg", "File:608.png", "File:608.jpg"]);
// also HEAD the failing browser URL
const head = await fetch("https://static.wikia.nocookie.net/onmyoji/images/d/d5/608.png/revision/latest?cb=20260930160027", { method: "HEAD" });
const head2 = await fetch("https://static.wikia.nocookie.net/onmyoji/images/d/d5/608.png/revision/latest", { method: "HEAD" });
return { info, withCB: head.status, withoutCB: head2.status };

