  // 2) souls 45-48 art via direct imageinfo
  const so = JSON.parse(fs.readFileSync('data/souls.json', 'utf8'));
  for (const s of so.filter(x => !x.art && x.no >= 45 && x.no <= 48)) {
    const file = 'M' + s.no + '.png';
    const j = await (await fetch(API + '?action=query&format=json&formatversion=2&prop=imageinfo&iiprop=url&titles=' + encodeURIComponent('File:' + file))).json();
