258: function heroFit(img) {
259:   // deterministic hero sizing: fit the artwork inside a 250(h)×260(w) box using its natural size
260:   const maxW = 340, maxH = 250;
261:   if (!img.naturalWidth || !img.naturalHeight) return;
262:   const s = Math.min(maxW / img.naturalWidth, maxH / img.naturalHeight);
263:   img.style.width = Math.round(img.naturalWidth * s) + "px";
264:   img.style.height = Math.round(img.naturalHeight * s) + "px";
265: }
