420:         ${(k.upgrades ?? []).length ? `<ul class="skill-ups">${k.upgrades.map((u) => `<li><b>Lv.${u.lvl}</b> ${esc(u.text)}</li>`).join("")}</ul>` : ""}
421:       </div>
422:     </div>`).join("");
423: 
424:   const bio = (s.bio ?? []).length ? `
425:     <section><h4>Biography</h4>
426:       <ul class="bio-list">${s.bio.map((b) => `<li>${esc(b.condition)}${b.reward ? ` <span class="bio-award">— reward: ${esc(b.reward)}</span>` : ""}</li>`).join("")}</ul></section>` : "";
427: 
428:   showModal(`
429:     <button class="close" aria-label="Close">✕</button>
430:     <div class="md">
431:       <div class="md-head">
432:         <img class="avatar${s.art ? " hero" : ""}" src="${s.art ?? s.localImage ?? s.imageUrl ?? ""}"
433:              alt="${esc(s.en)}" ${s.art ? `onload="heroFit(this)" onerror="this.onerror=null;this.src='${esc(s.localImage ?? s.imageUrl ?? "")}';this.classList.remove('hero');"` : ""}>
434:         <div>
