436:           <div class="md-names">${esc(s.cn)}${s.jp ? ` · ${esc(s.jp)}` : ""}${s.gl && s.gl !== s.en ? ` · ${esc(s.gl)}` : ""}</div>
437:           <div class="md-meta">
