439:             ${s.no ? `<span class="no" style="color:var(--faint);font-size:.78rem;">No.${s.no}</span>` : ""}
440:             ${s.cv ? `<span style="color:var(--muted);font-size:.82rem;">CV: ${esc(s.cv)}</span>` : ""}
441:           </div>
442:         </div>
443:       </div>
444:       ${s.intro ? `<section><h4>Introduction</h4><p>${esc(s.intro)}</p></section>` : ""}
445:       ${skills ? `<section><h4>Skills</h4>${skills}</section>` : ""}
446:       ${stats}
447:       ${bio}
448:       ${s.method ? `<section><h4>How to Obtain</h4><p>${esc(s.method)}</p></section>` : ""}
449:     </div>`);
450: }
