452: /* ============ Soul detail ============ */
453: function openSoulDetail(s) {
454:   if (!s) return;
455:   history.replaceState(null, "", `#${s.no}`);
456:   showModal(`
457:     <button class="close" aria-label="Close">✕</button>
458:     <div class="md">
459:       <div class="md-head">
460:         <img class="avatar${s.art ? " hero" : ""}" src="${s.art ?? s.localImage ?? s.imageUrl ?? ""}"
461:              alt="${esc(s.en)}" ${s.art ? `onload="heroFit(this)" onerror="this.onerror=null;this.src='${esc(s.localImage ?? s.imageUrl ?? "")}';this.classList.remove('hero');"` : ""}>
462:         <div>
463:           <h3>${esc(s.en)}</h3>
464:           <div class="md-names">${esc(s.cn)}${s.jp ? ` · ${esc(s.jp)}` : ""}</div>
465:           <div class="md-meta">
466:             <span class="badge ${s.type}">${esc(s.type)}</span>
467:             <span class="no" style="color:var(--faint);font-size:.78rem;">No.${s.no}</span>
468:             ${s.version ? `<span style="color:var(--muted);font-size:.82rem;">Servers: ${esc(s.version)}</span>` : ""}
469:           </div>
470:         </div>
471:       </div>
472:       ${s.combo2 ? `<section><h4>2-Set Bonus</h4><p>${esc(s.combo2)}</p></section>` : ""}
473:       ${s.combo4 ? `<section><h4>4-Set Bonus</h4><p>${esc(s.combo4)}</p></section>` : ""}
474:       ${s.location ? `<section><h4>Where to Find</h4><p>${esc(s.location)}</p></section>` : ""}
475:     </div>`);
476: }
