478: /* ============ Hash routing ============ */
479: function applyHash() {
480:   const no = location.hash.replace("#", "");
481:   if (!no) return;
482:   if (/^O/i.test(no)) {
483:     const ch = state.chars.find((c) => c.no.toUpperCase() === no.toUpperCase());
484:     if (ch) { openCharDetail(ch); return; }
485:   }
486:   if (/^OB\d/i.test(no)) {
487:     const bo = state.bonds.find((b) => b.no.toUpperCase() === no.toUpperCase());
488:     if (bo) { openBondDetail(bo); return; }
489:   }
490:   const sh = state.shikigami.find((s) => String(s.no) === no);
491:   if (sh) { openDetail(sh); return; }
492:   const so = state.souls.find((s) => String(s.no) === no);
493:   if (so) openSoulDetail(so);
494: }
495: window.addEventListener("hashchange", applyHash);
496: document.addEventListener("keydown", (e) => {
497:   if (e.key === "Escape") closeModal();
498: });
