500: /* boot by page */
501: const page = document.body.dataset.page;
502: window.addEventListener("DOMContentLoaded", async () => {
503:   if (page === "index") await renderIndex();
504:   else if (page === "shikigami") await renderShikigami();
505:   else if (page === "souls") await renderSouls();
506:   else if (page === "characters") await renderCharacters();
507:   else if (page === "bonding") await renderBonding();
