// get-fonts.mjs — one-off: self-host the webfonts (replaces the Google-Fonts CDN links).
// Zen Old Mincho 500/700 (latin + latin-ext subsets) and Marcellus 400.
import fs from "node:fs";
import path from "node:path";

const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36";
const CSS_URL =
  "https://fonts.googleapis.com/css2?family=Marcellus&family=Zen+Old+Mincho:wght@500;700&display=swap";
const OUT = "assets/fonts";

fs.mkdirSync(OUT, { recursive: true });
const css = await (await fetch(CSS_URL, { headers: { "User-Agent": UA } })).text();

/* Parse @font-face blocks; keep only latin and latin-ext subsets. */
const blocks = [...css.matchAll(/\/\* ([a-z-]+) \*\/\s*@font-face\s*\{([\s\S]*?)\}/g)];
const wanted = blocks.filter(([, subset]) => subset === "latin" || subset === "latin-ext");
let outCss = "";
for (const [, subset, body] of wanted) {
  const family = body.match(/font-family:\s*'([^']+)'/)[1];
  const weight = body.match(/font-weight:\s*(\d+)/)[1];
  const style = (body.match(/font-style:\s*(\w+)/) ?? [, "normal"])[1];
  const url = body.match(/url\((https:[^)]+\.woff2)\)/)[1];
  const fname = `${family.toLowerCase().replaceAll(" ", "-")}-${weight}-${style}-${subset}.woff2`;
  const buf = Buffer.from(await (await fetch(url, { headers: { "User-Agent": UA } })).arrayBuffer());
  fs.writeFileSync(path.join(OUT, fname), buf);
  const ranges = body.match(/unicode-range:\s*([^;]+);/)?.[1] ?? "";
  outCss += `@font-face {\n  font-family: "${family}";\n  font-style: ${style};\n  font-weight: ${weight};\n  font-display: swap;\n  src: url("../assets/fonts/${fname}") format("woff2");\n  unicode-range: ${ranges};\n}\n`;
  console.log("saved", fname, (buf.length / 1024).toFixed(0) + "KB");
}
fs.writeFileSync("css/fonts.css", outCss);
console.log("css/fonts.css written with", wanted.length, "faces");

/* ============================================================
   Onmyoji Codex — design system v6 ("Evolved Heian Night")
   Palette & typography are an original Heian-game-inspired theme:
   night-lacquer indigo ground, gold hairlines, vermillion seals.
   Mobile-first: base styles are the phone layout; min-width layers on.
   ============================================================ */
:root {
  /* ground + surfaces */
  --bg: #0e0913;
  --bg-soft: #151022;
  --surface: #1b1526;
  --surface-2: #251c33;
  --border: #40304f;
  --border-soft: #2c2138;

  /* ink */
  --text: #efe7dd;
  --muted: #ab9f97;
  --faint: #7e7384;

  /* seals */
  --vermillion: #b03027;
  --vermillion-hi: #d95546;
  --gold: #c9a227;
  --gold-soft: #e5cf7a;

  /* rgb triplets — every translucent accent composes from these */
  --gold-rgb: 201 162 39;
  --verm-rgb: 176 48 39;
  --sp-rgb: 224 85 76;
  --ssr-rgb: 212 175 55;
  --sr-rgb: 155 111 212;
  --r-rgb: 93 159 212;
  --n-rgb: 139 139 143;

  /* per-rarity accent triplet; cards override this */
  --rar-rgb: var(--gold-rgb);

  /* motion */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --dur-1: 150ms;
  --dur-2: 320ms;
  --dur-3: 600ms;

  /* elevation */
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 12px 32px rgb(0 0 0 / 0.5), 0 2px 8px rgb(0 0 0 / 0.4);
  --shadow-soft: 0 6px 18px rgb(0 0 0 / 0.35);

  /* type */
  --font-serif: "Zen Old Mincho", "Yu Mincho", "Hiragino Mincho ProN", "Noto Serif JP", serif;
  --font-latin: "Marcellus", "Zen Old Mincho", serif;
  --font-ui: system-ui, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background:
    radial-gradient(1200px 600px at 85% -10%, rgb(var(--verm-rgb) / 0.10), transparent 60%),
    radial-gradient(900px 500px at -10% 20%, rgb(var(--gold-rgb) / 0.06), transparent 55%),
    var(--bg);
  color: var(--text);
  font-family: var(--font-serif);
  line-height: 1.6;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* ---------- browser surfaces, themed from the palette ---------- */
::selection { background: rgb(var(--verm-rgb) / 0.45); color: var(--text); }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 6px; }
::-webkit-scrollbar-thumb:hover { background: #54406b; }
input, textarea { caret-color: var(--gold-soft); }
:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: 4px;
}
:focus:not(:focus-visible) { outline: none; }

/* ---------- Navigation ---------- */
.nav {
  position: sticky;
  top: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.8rem clamp(1rem, 4vw, 3rem);
  background: rgb(14 9 19 / 0.82);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-soft);
}
.nav .brand {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  text-decoration: none;
  color: var(--text);
  font-size: 1.15rem;
  letter-spacing: 0.12em;
  flex-shrink: 0;
}
.seal {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--vermillion), #7d1f18);
  color: #f6e9d8;
  border-radius: 7px;
  font-size: 1.05rem;
  font-weight: 700;
  box-shadow: 0 2px 10px rgb(var(--verm-rgb) / 0.45);
  font-family: var(--font-serif);
}
.nav .brand small {
  display: block;
  color: var(--muted);
  font-size: 0.68rem;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  font-family: var(--font-serif);
}
.nav nav {
  display: flex;
  gap: 1.2rem;
  overflow-x: auto;
  scrollbar-width: none;
}
.nav nav::-webkit-scrollbar { display: none; }
.nav nav a {
  color: var(--muted);
  text-decoration: none;
  font-size: 0.95rem;
  letter-spacing: 0.08em;
  padding: 0.3rem 0;
  border-bottom: 2px solid transparent;
  transition: color var(--dur-1) var(--ease-in-out), border-color var(--dur-1) var(--ease-in-out);
  white-space: nowrap;
}
.nav nav a:hover, .nav nav a.active { color: var(--gold-soft); border-color: var(--vermillion); }

/* ---------- Layout ---------- */
.wrap { max-width: 1240px; margin: 0 auto; padding: 0 clamp(1rem, 4vw, 3rem); }
.section { padding: 3rem 0; }

/* ---------- Hero ---------- */
.hero { position: relative; padding: 3.5rem 0 3rem; overflow: hidden; }
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(700px 380px at 70% 30%, rgb(var(--verm-rgb) / 0.16), transparent 65%);
  pointer-events: none;
}
.hero-inner { position: relative; display: grid; gap: 1.8rem; align-items: center; }
.hero-mono {
  font-size: clamp(1.5rem, 3.4vw, 2.4rem);
  letter-spacing: 0.4em;
  color: var(--gold-soft);
  position: relative;
  text-shadow: 0 0 24px rgb(233 207 122 / 0.25);
}
/* the breathing glow: a blurred duplicate over the glyphs, pulsing slowly */
.hero-mono::after {
  content: attr(data-glyphs);
  position: absolute;
  inset: 0;
  color: var(--gold-soft);
  filter: blur(14px);
  opacity: 0.4;
  animation: mono-breath 7s var(--ease-in-out) infinite alternate;
  pointer-events: none;
}
@keyframes mono-breath { to { opacity: 0.85; } }
.hero h1 {
  margin: 0 0 0.4rem;
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.12;
  font-family: var(--font-latin);
  text-wrap: balance;
}
.hero h1 .accent { color: var(--vermillion-hi); }
.hero .sub {
  color: var(--muted);
  max-width: 68ch;
  margin-bottom: 1.6rem;
  font-size: 1.05rem;
}
.hero .cta { display: flex; gap: 1rem; flex-wrap: wrap; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.65rem 1.5rem;
  border-radius: var(--radius-sm);
  font-family: var(--font-serif);
  font-size: 0.95rem;
  letter-spacing: 0.1em;
  text-decoration: none;
  cursor: pointer;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  transition:
    transform var(--dur-1) var(--ease-out),
    border-color var(--dur-1) var(--ease-in-out),
    box-shadow var(--dur-2) var(--ease-in-out),
    color var(--dur-1) var(--ease-in-out),
    background-color var(--dur-1) var(--ease-in-out);
}
.btn:hover { border-color: var(--gold); color: var(--gold-soft); transform: translateY(-1px); }
.btn:active { transform: translateY(0); box-shadow: inset 0 2px 6px rgb(0 0 0 / 0.35); }
.btn:disabled, .btn[aria-disabled="true"] { opacity: 0.45; cursor: not-allowed; transform: none; box-shadow: none; }
.btn.primary {
  background: linear-gradient(135deg, var(--vermillion), #8a241c);
  border-color: transparent;
  color: #f9ecdd;
  box-shadow: 0 4px 18px rgb(var(--verm-rgb) / 0.4);
}
.btn.primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 26px rgb(var(--sp-rgb) / 0.45);
  color: #fff4e8;
}
/* loading state (spinner lane) */
.btn.is-loading { color: transparent; pointer-events: none; }
.btn.is-loading::after {
  content: "";
  position: absolute;
  width: 1.1em; height: 1.1em;
  margin-inline-start: -0.55em;
  border: 2px solid rgb(255 255 255 / 0.35);
  border-top-color: transparent;
  border-radius: 50%;
  animation: btn-spin 0.7s linear infinite;
}
@keyframes btn-spin { to { transform: rotate(360deg); } }

/* ---------- Stat band ---------- */
.stats-band {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 1rem;
}
.stat-card {
  background: linear-gradient(160deg, var(--surface-2), var(--surface));
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 1.1rem 1.3rem;
  transition: border-color var(--dur-2) var(--ease-in-out), transform var(--dur-2) var(--ease-out);
}
.stat-card:hover { border-color: rgb(var(--gold-rgb) / 0.35); transform: translateY(-2px); }
.stat-card .num {
  font-size: 2.2rem;
  font-family: var(--font-latin);
  color: var(--gold-soft);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}
.stat-card .label { color: var(--muted); font-size: 0.85rem; letter-spacing: 0.14em; text-transform: uppercase; }
.stat-card .mini { margin-top: 0.55rem; display: flex; gap: 0.55rem; font-size: 0.78rem; color: var(--faint); flex-wrap: wrap; }
.stat-card .mini b { color: var(--text); font-weight: 600; }

/* ---------- Section headings ---------- */
.sec-head { display: flex; align-items: baseline; gap: 1rem; margin-bottom: 1.6rem; flex-wrap: wrap; }
.sec-head h2 { margin: 0; font-family: var(--font-latin); font-size: 1.8rem; letter-spacing: 0.1em; }
.sec-head .jp { color: var(--vermillion-hi); font-size: 1.15rem; }
.sec-head .spacer { flex: 1; border-bottom: 1px solid var(--border-soft); min-width: 2rem; }
.sec-head a { color: var(--muted); font-size: 0.85rem; text-decoration: none; letter-spacing: 0.1em; }
.sec-head a:hover { color: var(--gold-soft); }

/* ---------- Cards grid (ema-plaque language) ---------- */
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 14px; }

.card {
  --sheen: rgb(233 207 122 / 0.2);
  position: relative;
  background: linear-gradient(165deg, var(--surface-2), var(--surface));
  border: 1px solid rgb(var(--rar-rgb) / 0.3);
  border-radius: var(--radius);
  padding: 10px 10px 14px;
  cursor: pointer;
  text-align: center;
  overflow: hidden;
  transition:
    transform var(--dur-2) var(--ease-out),
    border-color var(--dur-2) var(--ease-in-out),
    box-shadow var(--dur-2) var(--ease-in-out);
}
.card:hover {
  transform: translateY(-6px);
  border-color: rgb(var(--rar-rgb) / 0.8);
  box-shadow: var(--shadow), 0 0 24px rgb(var(--rar-rgb) / 0.12);
}
.card:active { transform: translateY(-3px) scale(0.99); }

/* rarity accents — full hairline tint, never a one-side bar */
.card[data-rarity="SSR"] { --rar-rgb: var(--ssr-rgb); }
.card[data-rarity="SP"]  { --rar-rgb: var(--sp-rgb); --sheen: rgb(var(--sp-rgb) / 0.22); }
.card[data-rarity="SR"]  { --rar-rgb: var(--sr-rgb); }
.card[data-rarity="R"]   { --rar-rgb: var(--r-rgb); }
.card[data-rarity="N"]   { --rar-rgb: var(--n-rgb); }

/* gilded shimmer lane: sweeps on hover; SSR also breathes an idle sweep */
.card .sheen {
  position: absolute;
  top: -30%;
  left: -30%;
  width: 60%;
  height: 160%;
  background: linear-gradient(105deg, transparent 40%, var(--sheen) 50%, transparent 60%);
  transform: skewX(-18deg) translateX(-80%);
  opacity: 0;
  pointer-events: none;
}
.card:hover .sheen { animation: sheen-sweep 0.9s var(--ease-out); }
.card[data-rarity="SSR"].in-view .sheen,
.card[data-rarity="SP"].in-view .sheen {
  animation: sheen-idle 8s var(--ease-in-out) infinite;
  animation-delay: calc(var(--st, 0ms) * 3 + 2.5s);
}
@keyframes sheen-sweep {
  0%   { transform: skewX(-18deg) translateX(-80%); opacity: 0; }
  15%  { opacity: 1; }
  100% { transform: skewX(-18deg) translateX(340%); opacity: 0; }
}
@keyframes sheen-idle {
  0%, 12% { transform: skewX(-18deg) translateX(-80%); opacity: 0.4; }
  8%      { opacity: 1; }
  24%, 100% { transform: skewX(-18deg) translateX(340%); opacity: 0; }
}

.card img {
  width: 100%;
  aspect-ratio: 1;
  object-fit: contain;
  border-radius: var(--radius-sm);
  background: radial-gradient(120px 90px at 50% 45%, rgb(var(--gold-rgb) / 0.08), transparent 75%);
  transition: transform var(--dur-3) var(--ease-out);
}
.card:hover img { transform: scale(1.06); }
/* error state: image missing or unwriteable — show an ornament, never a broken glyph */
.card.img-err img { display: none; }
.card.img-err::before {
  content: attr(data-initial);
  display: grid;
  place-items: center;
  aspect-ratio: 1;
  font-family: var(--font-latin);
  font-size: 2.4rem;
  color: rgb(var(--rar-rgb) / 0.55);
  background: radial-gradient(120px 90px at 50% 45%, rgb(var(--gold-rgb) / 0.05), transparent 75%);
}
.card .name { margin-top: 8px; font-size: 0.9rem; line-height: 1.35; letter-spacing: 0.04em; transition: color var(--dur-1) var(--ease-in-out); }
.card .cn { color: var(--muted); font-size: 0.75rem; }
.card .meta { display: flex; justify-content: center; gap: 6px; margin-top: 6px; align-items: center; }
.card .no { color: var(--faint); font-size: 0.7rem; font-family: var(--font-latin); font-variant-numeric: tabular-nums; }

/* ---------- Entrance choreography (opt-in via .js-fx on <html>) ---------- */
.js-fx .card, .js-fx .soul-row, .js-fx .stat-card {
  opacity: 0;
  transform: translateY(16px);
}
.js-fx .card.in-view, .js-fx .soul-row.in-view, .js-fx .stat-card.in-view {
  opacity: 1;
  transform: none;
  transition:
    opacity var(--dur-3) var(--ease-out) var(--st, 0ms),
    transform var(--dur-3) var(--ease-out) var(--st, 0ms),
    border-color var(--dur-1) var(--ease-in-out),
    box-shadow var(--dur-2) var(--ease-in-out);
}

/* ---------- Badges ---------- */
.badge {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid;
  text-transform: uppercase;
  font-family: var(--font-serif);
  color: var(--gold-soft);
  border-color: rgb(var(--gold-rgb) / 0.5);
  background: rgb(var(--gold-rgb) / 0.08);
}
.badge.SSR { color: var(--gold-soft); border-color: rgb(var(--ssr-rgb) / 0.5); background: rgb(var(--ssr-rgb) / 0.08); }
.badge.SR  { color: #c9adf0; border-color: rgb(var(--sr-rgb) / 0.5); background: rgb(var(--sr-rgb) / 0.08); }
.badge.R   { color: #a4cdf5; border-color: rgb(var(--r-rgb) / 0.5); background: rgb(var(--r-rgb) / 0.08); }
.badge.SP  { color: #f1958d; border-color: rgb(var(--sp-rgb) / 0.55); background: rgb(var(--sp-rgb) / 0.1); }
.badge.N   { color: #b3b3b7; border-color: rgb(var(--n-rgb) / 0.4); background: rgb(var(--n-rgb) / 0.08); }

/* ---------- Toolbar ---------- */
.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  align-items: center;
  margin-bottom: 1.6rem;
  position: sticky;
  top: 56px;
  z-index: 40;
  background: rgb(14 9 19 / 0.78);
  backdrop-filter: blur(8px);
  padding: 0.8rem 0;
  border-bottom: 1px solid var(--border-soft);
}
.search { flex: 1 1 240px; max-width: 380px; position: relative; }
.search .search-ico {
  position: absolute;
  left: 0.75rem;
  top: 50%;
  translate: 0 -50%;
  width: 16px;
  height: 16px;
  color: var(--muted);
  pointer-events: none;
}
.search input {
  width: 100%;
  padding: 0.55rem 0.9rem 0.55rem 2.4rem;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: var(--radius-sm);
  font-family: var(--font-serif);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--dur-1) var(--ease-in-out), box-shadow var(--dur-2) var(--ease-in-out);
}
.search input:hover { border-color: var(--faint); }
.search input:focus { border-color: var(--gold); box-shadow: 0 0 0 3px rgb(var(--gold-rgb) / 0.15); }
.search input::placeholder { color: var(--muted); }

.chips { display: flex; gap: 0.5rem; flex-wrap: wrap; }
.chip {
  padding: 0.35rem 0.95rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-family: var(--font-ui);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  transition: color var(--dur-1) var(--ease-in-out), border-color var(--dur-1) var(--ease-in-out), background-color var(--dur-1) var(--ease-in-out), transform var(--dur-1) var(--ease-out);
}
.chip:hover { color: var(--text); border-color: var(--faint); }
.chip:active { transform: scale(0.96); }
.chip.on { color: #f3e6cc; background: linear-gradient(135deg, var(--vermillion), #8a241c); border-color: transparent; }

/* ---------- Custom sort (ARIA listbox; a native select never ships) ---------- */
.menu { position: relative; }
.menu-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.85rem;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: var(--radius-sm);
  font-family: var(--font-serif);
  font-size: 0.88rem;
  letter-spacing: 0.06em;
  cursor: pointer;
  transition: border-color var(--dur-1) var(--ease-in-out), boyd none;
}
.menu-btn:hover { border-color: var(--faint); }
.menu-btn .chevr {
  width: 14px; height: 14px;
  color: var(--muted);
  transition: transform var(--dur-1) var(--ease-in-out);
}
.menu-btn[aria-expanded="true"] .chevr { transform: rotate(180deg); color: var(--gold-soft); }
.menu-list {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  min-width: 210px;
  margin: 0;
  padding: 0.4rem;
  list-style: none;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow);
  z-index: 60;
  animation: menu-in var(--dur-1) var(--ease-out);
}
.menu-list[hidden] { display: none; }
@keyframes menu-in { from { opacity: 0; transform: translateY(-6px); } }
.menu-list li {
  padding: 0.45rem 0.8rem;
  border-radius: 6px;
  color: var(--muted);
  cursor: pointer;
  font-family: var(--font-ui);
  font-size: 0.85rem;
  letter-spacing: 0.04em;
  transition: background-color var(--dur-1) var(--ease-in-out), color var(--dur-1) var(--ease-in-out);
}
.menu-list li:hover, .menu-list li:focus-visible { color: var(--text); background: rgb(var(--gold-rgb) / 0.08); outline: none; }
.menu-list li[aria-selected="true"] { color: var(--gold-soft); }

.count-note { color: var(--faint); font-size: 0.8rem; letter-spacing: 0.08em; font-family: var(--font-ui); font-variant-numeric: tabular-nums; display: none; }

/* ---------- Souls list ---------- */
.soul-list { display: flex; flex-direction: column; gap: 8px; }
.soul-row {
  display: grid;
  grid-template-columns: 52px 1fr auto;
  gap: 1rem;
  align-items: center;
  padding: 0.7rem 1rem;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: linear-gradient(160deg, var(--surface-2), var(--surface));
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  transition:
    transform var(--dur-2) var(--ease-out),
    border-color var(--dur-2) var(--ease-in-out),
    opacity var(--dur-3) var(--ease-out) var(--st, 0ms);
}
.soul-row:hover { border-color: rgb(var(--gold-rgb) / 0.4); transform: translateX(4px); }
.soul-row:active { transform: translateX(2px) scale(0.995); }
.soul-row img { width: 46px; height: 46px; object-fit: contain; }
.soul-row .names { display: flex; flex-direction: column; }
.soul-row .en { font-size: 1rem; letter-spacing: 0.05em; font-variant-numeric: tabular-nums; }
.soul-row .cn { color: var(--muted); font-size: 0.78rem; }

/* ---------- Skill cards (detail modal) ---------- */
.skill-card {
  display: grid;
  grid-template-columns: 58px 1fr;
  gap: 0.9rem;
  padding: 0.9rem 0;
  border-bottom: 1px dashed var(--border-soft);
}
.skill-card:last-child { border-bottom: none; }
.skill-icon {
  width: 52px; height: 52px;
  object-fit: contain;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-soft);
  background: radial-gradient(80px 60px at 50% 45%, rgb(var(--gold-rgb) / 0.10), transparent 75%);
}
.skill-head { display: flex; align-items: center; gap: 0.6rem; flex-wrap: wrap; }
.skill-head strong { font-size: 1rem; letter-spacing: 0.04em; }
.skill-tags { display: flex; gap: 0.4rem; margin-left: auto; flex-wrap: wrap; }
.skill-kind {
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold-soft);
  border: 1px solid rgb(var(--gold-rgb) / 0.35);
  border-radius: 999px;
  padding: 1px 8px;
}
.skill-tags span:not(.skill-kind) {
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  color: var(--muted);
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  padding: 1px 8px;
}
.skill-cost { color: var(--faint); font-size: 0.75rem; margin-top: 0.15rem; letter-spacing: 0.08em; font-family: var(--font-ui); }
.skill-line { color: var(--vermillion-hi); font-size: 0.85rem; font-style: italic; margin: 0.35rem 0 0; }
.skill-body p { margin: 0.3rem 0 0; color: #d4cabf; font-size: 0.88rem; }
.skill-ups { margin: 0.4rem 0 0; padding-left: 1rem; color: var(--muted); font-size: 0.8rem; font-family: var(--font-ui); }
.skill-ups li { margin: 0.15rem 0; }
.skill-ups b { color: var(--gold-soft); font-weight: 600; }

.bio-list { margin: 0; padding-left: 1.1rem; color: #d4cabf; font-size: 0.88rem; }
.bio-list li { margin: 0.3rem 0; }
.bio-award { color: var(--gold-soft); font-size: 0.82rem; }

/* ---------- Characters page (Onmyoji / Champion / Bondling) ---------- */
.thumb-row { display: flex; flex-wrap: wrap; gap: 0.7rem; }
.thumb {
  width: 150px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 1px solid var(--border-soft);
  background: rgb(0 0 0 / 0.25);
  transition: transform var(--dur-2) var(--ease-out), border-color var(--dur-2) var(--ease-in-out);
}
.thumb:hover { transform: translateY(-3px); border-color: rgb(var(--gold-rgb) / 0.4); }
.thumb img { display: block; width: 100%; height: auto; }
.soul-row .badge { color: var(--gold-soft); border-color: rgb(var(--gold-rgb) / 0.4); background: rgb(var(--gold-rgb) / 0.08); }

/* type table (souls) */
.type-col { min-width: 72px; text-align: center; }

/* ---------- Modal ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgb(8 5 10 / 0.72);
  backdrop-filter: blur(6px);
  display: none;
  place-items: center;
  z-index: 100;
  padding: 1.2rem;
}
.modal-backdrop.open { display: grid; animation: bd-in var(--dur-1) var(--ease-out); }
@keyframes bd-in { from { opacity: 0; } }
.modal {
  width: min(760px, 94vw);
  max-height: 88vh;
  overflow-y: auto;
  background: linear-gradient(170deg, var(--surface-2), var(--bg-soft));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.8rem 2rem;
  position: relative;
  animation: md-in var(--dur-2) var(--ease-out);
}
@keyframes md-in { from { opacity: 0; transform: translateY(16px) scale(0.97); } }
.modal::before {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 3px;
  background: linear-gradient(90deg, var(--vermillion), var(--gold) 50%, transparent);
  border-radius: 3px 3px 0 0;
}
.modal .close {
  position: absolute;
  top: 0.7rem; right: 0.7rem;
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  background: none;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--muted);
  cursor: pointer;
  transition: color var(--dur-1) var(--ease-in-out), background-color var(--dur-1) var(--ease-in-out);
}
.modal .close svg { width: 16px; height: 16px; }
.modal .close:hover { color: var(--vermillion-hi); background: rgb(var(--verm-rgb) / 0.12); }
.md-head { display: flex; gap: 1.4rem; flex-direction: column; align-items: center; text-align: center; }
.md-head img { flex-shrink: 0; }
.md-head img.avatar {
  width: 120px; height: 120px;
  object-fit: contain;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: radial-gradient(100px 80px at 50% 45%, rgb(var(--gold-rgb) / 0.1), transparent 75%);
}
/* large full artwork variant — sized precisely via heroFit() onload (natural aspect) */
.md-head img.avatar.hero {
  object-fit: contain;
  border-radius: var(--radius-sm);
  border: none;
  background: none;
  filter: drop-shadow(0 6px 14px rgb(0 0 0 / 0.45));
  animation: hero-rise 0.5s var(--ease-out) 0.1s backwards;
}
@keyframes hero-rise { from { opacity: 0; transform: translateY(14px) scale(0.98); } }
.md-head h3 { margin: 0 0 0.2rem; font-family: var(--font-latin); font-size: 1.6rem; letter-spacing: 0.05em; text-wrap: balance; }
.md-names { color: var(--muted); font-size: 0.88rem; margin-bottom: 0.4rem; }
.md-meta { display: flex; gap: 0.6rem; flex-wrap: wrap; align-items: center; justify-content: center; margin-top: 0.4rem; }
.md section { margin-top: 1.2rem; animation: sec-in 0.45s var(--ease-out) 0.12s backwards; }
.md section:nth-child(2) { animation-delay: 0.18s; }
.md section:nth-child(3) { animation-delay: 0.24s; }
.md section:nth-child(n+4) { animation-delay: 0.3s; }
@keyframes sec-in { from { opacity: 0; transform: translateY(10px); } }
.md h4 {
  margin: 0 0 0.5rem;
  color: var(--gold-soft);
  font-size: 0.85rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-family: var(--font-serif);
}
.md p { margin: 0; color: #d4cabf; font-size: 0.93rem; }
table.mini {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
  font-family: var(--font-ui);
  font-variant-numeric: tabular-nums;
}
table.mini th, table.mini td {
  padding: 6px 10px;
  border: 1px solid var(--border-soft);
  text-align: center;
}
table.mini th {
  background: rgb(var(--verm-rgb) / 0.16);
  color: #e8ddca;
  letter-spacing: 0.1em;
  font-weight: 600;
}
table.mini td { color: #cbc0b5; }
table.mini tr td:first-child, table.mini tr th:first-child {
  text-align: left;
  letter-spacing: normal;
  font-family: var(--font-serif);
}
.md .link-out { margin-top: 1.4rem; }

/* ---------- Footer ---------- */
footer {
  margin-top: 4rem;
  border-top: 1px solid var(--border-soft);
  padding: 2.2rem 0 3rem;
  color: var(--faint);
  font-size: 0.85rem;
}
footer .wrap { display: flex; flex-direction: column; gap: 0.5rem; }
footer a { color: var(--muted); }
footer a:hover { color: var(--gold-soft); }

/* ---------- Utilities ---------- */
.skeleton {
  height: 210px;
  border-radius: var(--radius);
  background: linear-gradient(100deg, var(--surface) 30%, var(--surface-2) 50%, var(--surface) 70%);
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite;
}
@keyframes shimmer { to { background-position: -200% 0; } }
.center-note { text-align: center; color: var(--muted); padding: 3rem 0; }

/* ---------- Desktop restoration (min-width layers) ---------- */
@media (min-width: 720px) {
  .hero { padding: 5.5rem 0 4rem; }
  .hero-inner { grid-template-columns: auto 1fr; gap: 2.5rem; }
  .hero-mono {
    writing-mode: vertical-rl;
    border-left: 2px solid rgb(var(--gold-rgb) / 0.35);
    border-right: 2px solid rgb(var(--gold-rgb) / 0.35);
    padding: 1.2rem 0.7rem;
    letter-spacing: 0.55em;
  }
  .md-head { gap: 1.4rem; flex-direction: row; align-items: flex-start; text-align: left; }
  .md-head img.avatar { width: 132px; height: 132px; }
  .md-meta { justify-content: flex-start; }
  .count-note { display: inline; margin-left: auto; }
  .section { padding: 3.5rem 0; }
}

/* ---------- Reduced motion: content visible, motion off ---------- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .js-fx .card, .js-fx .soul-row, .js-fx .stat-card { opacity: 1; transform: none; }
  .md-head img.avatar.hero, .md section { opacity: 1; transform: none; }
}

