// swap-close.mjs — one-off: replace the unicode ✕ close button with the drawn SVG icon.
import fs from "node:fs";
const path = "js/app.js";
let s = fs.readFileSync(path, "utf8");
const rx = /<button class="close" aria-label="Close">[^<]*<\/button>/g;
const n = (s.match(rx) ?? []).length;
s = s.replaceAll(rx, '<button class="close" aria-label="Close">${CLOSE_SVG}</button>');
fs.writeFileSync(path, s, "utf8");
console.log("replaced", n, "close buttons; leftover glyphs:", (s.match(/✕/g) ?? []).length);

// page-sweep.mjs — one-off: apply the v6 head/tool changes to every page.
import fs from "node:fs";

const FONT_HEAD_OLD = [
  '  <link rel="preconnect" href="https://fonts.googleapis.com">',
  '  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>',
  '  <link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Zen+Old+Mincho:wght@500;700&display=swap" rel="stylesheet">',
  '  <link rel="stylesheet" href="css/style.css?v=5">',
].join("\n");
const FONT_HEAD_NEW = [
  '  <meta name="theme-color" content="#0e0913">',
  '  <link rel="stylesheet" href="css/fonts.css?v=6">',
  '  <link rel="stylesheet" href="css/style.css?v=6">',
].join("\n");

const SEARCH_SVG =
  '<svg class="search-ico" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><circle cx="7" cy="7" r="4.4"/><path d="m10.4 10.4 3 3"/></svg>';

const SORT_OLD = `      <select class="sort" id="sort" aria-label="Sort order">
        <option value="no-desc">No. → new</option>
        <option value="no-asc">No. → old</option>
        <option value="rar">Rarity</option>
        <option value="en">Name A→Z</option>
      </select>`;

const SORT_NEW = `      <div class="menu" id="sort-menu">
        <button class="menu-btn" id="sort-btn" aria-haspopup="listbox" aria-expanded="false" aria-controls="sort-list" aria-label="Sort order">
          <span id="sort-label">Newest</span>
          <svg class="chevr" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg>
        </button>
        <ul class="menu-list" id="sort-list" role="listbox" aria-label="Sort order" hidden>
          <li role="option" id="sort-opt-new" data-value="no-desc" aria-selected="true">Newest first</li>
          <li role="option" data-value="no-asc" aria-selected="false">Oldest first</li>
          <li role="option" data-value="rar" aria-selected="false">Rarity first</li>
          <li role="option" data-value="en" aria-selected="false">Name A–Z</li>
        </ul>
      </div>`;

const pages = ["index.html", "shikigami.html", "souls.html", "bonding.html", "characters.html"];
for (const f of pages) {
  let s = fs.readFileSync(f, "utf8");
  let log = [];
  if (s.includes("fonts.googleapis.com")) {
    s = s.replace(FONT_HEAD_OLD, FONT_HEAD_NEW);
    log.push("font-head:" + (s.includes("fonts.googleapis.com") ? "STILL THERE" : "ok"));
  }
  s = s.replaceAll("js/app.js?v=2", "js/app.js?v=3");
  // inject the drawn search icon before the input in every search box
  const rx = /(<div class="search">)(\s*<input [^>]*aria-label=)([^>]*>)/g;
  s = s.replace(rx, `$1${"$"}{SEARCH_SVG}$2$3`);
  if (s.includes(SORT_OLD)) { s = s.replace(SORT_OLD, SORT_NEW); log.push("sort-menu:ok"); }
  fs.writeFileSync(f, s, "utf8");
  console.log(f, "|", log.join(", ") || "head done");
}

// fix-search-ico.mjs — one-off: inject the drawn search icon into every .search box.
