// page-check.mjs — real-browser console-error sweep + hero measurements for the codex.
import { chromium } from "playwright";

const pages = [
  ["index", "http://localhost:8123/index.html?build=" + Date.now()],
  ["shikigami", "http://localhost:8123/shikigami.html?build=" + Date.now() + "#205"],
  ["souls", "http://localhost:8123/souls.html?build=" + Date.now() + "#1"],
  ["bonding", "http://localhost:8123/bonding.html?build=" + Date.now() + "#OB02"],
  ["characters", "http://localhost:8123/characters.html?build=" + Date.now() + "#O1"],
];
const out = {};
const browser = await chromium.launch({ channel: "chrome", headless: true });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });

for (const [name, url] of pages) {
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push("PAGEERROR: " + e.message.slice(0, 160)));
  page.on("console", (m) => { if (m.type() === "error") errors.push("CONSOLE: " + m.text().slice(0, 160)); });
  if (url.toString().includes("\n")) console.log("bad");
  await page.goto(url, { waitUntil: "networkidle", timeout: 45000 }).catch((e) => {
    errors.push("NAV: " + e.message.slice(0, 120));
  });
  await page.waitForTimeout(600);
  const info = await page.evaluate(() => {
    const g = document.querySelector.bind(document);
    return {
      title: document.title,
      cards: document.querySelectorAll(".card").length,
      soulRows: document.querySelectorAll(".soul-row").length,
      statCards: document.querySelectorAll(".stat-card").length,
      modal: !!g("#modal-backdrop .modal"),
      modalTitle: g("#modal-backdrop .md-head h3")?.textContent ?? null,
      heroImg: (() => { const i = g("#modal-backdrop .avatar"); return i ? `${i.className}|${Math.round(i.getBoundingClientRect().width)}x${Math.round(i.getBoundingClientRect().height)}` : null; })(),
      menu: !!g("#sort-menu"),
      sheens: document.querySelectorAll(".sheen").length,
      revealed: document.querySelectorAll(".card.in-view").length,
      fontOk: document.fonts.check('16px "Zen Old Mincho"') && document.fonts.check('16px "Marcellus"'),
    };
  });
  out[name] = { errors, ...info };
  await page.close();
}
await browser.close();
console.log(JSON.stringify(out, null, 2));

