// shoot.mjs — capture review screenshots: first viewport + full page, desktop + mobile.
import path from "node:path";
import fs from "node:fs";
import { createRequire } from "node:module";
const { chromium } = createRequire(path.resolve("ux-ui-agent-skills/package.json"))("playwright");

const OUT = path.join(".impeccable", "review");
fs.mkdirSync(OUT, { recursive: true });
const base = "http://localhost:8123";
const t = Date.now();

const shots = [
  { name: "index", url: `${base}/index.html?cap=${t}`, w: 1440, h: 900, full: true },
  { name: "shikigami", url: `${base}/shikigami.html?cap=${t}`, w: 1440, h: 900, full: true },
  { name: "souls", url: `${base}/souls.html?cap=${t}`, w: 1440, h: 900, full: true },
  { name: "bonding", url: `${base}/bonding.html?cap=${t}`, w: 1440, h: 900, full: true },
  { name: "characters", url: `${base}/characters.html?cap=${t}`, w: 1440, h: 900, full: true },
  { name: "mobile-index", url: `${base}/index.html?cap=${t}`, w: 390, h: 844, full: true },
  { name: "mobile-shikigami", url: `${base}/shikigami.html?cap=${t}`, w: 390, h: 844, full: false },
];

const browser = await chromium.launch({ channel: "chrome", headless: true });
for (const s of shots) {
  const ctx = await browser.newContext({ viewport: { width: s.w, height: s.h }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await page.goto(s.url, { waitUntil: "networkidle", timeout: 45000 });
  // force reveals by scrolling through the page, then return to top
  await page.evaluate(async () => {
    const step = innerHeight * 0.7;
    for (let y = 0; y < document.body.scrollHeight; y += step) { scrollTo(0, y); await new Promise(r => setTimeout(r, 60)); }
    scrollTo(0, 0);
  });
  await page.waitForTimeout(900);
  await page.screenshot({ path: path.join(OUT, `${s.name}.png`), fullPage: s.full });
  const revealed = await page.evaluate(() => document.querySelectorAll(".card.in-view, .stat-card.in-view").length);
  const cards = await page.evaluate(() => document.querySelectorAll(".card, .stat-card").length);
  console.log(`${s.name}: ${s.w}x${s.h} full=${s.full} | revealed ${revealed}/${cards}`);
  await ctx.close();
}
await browser.close();

