// probe-md.mjs — why is .md-head column at 1440? measure computed styles + media query state.
import path from "node:path";
import { createRequire } from "node:module";
const { chromium } = createRequire(path.resolve("ux-ui-agent-skills/package.json"))("playwright");

const browser = await chromium.launch({ channel: "chrome", headless: true });
const page = await (await browser.newContext({ viewport: { width: 1440, height: 980 } })).newPage();
await page.goto(`http://localhost:8123/shikigami.html?probe=${Date.now()}#259`, { waitUntil: "networkidle" });
await page.waitForTimeout(500);
const res = await page.evaluate(() => {
  const head = document.querySelector("#modal-backdrop .md-head");
  const img = document.querySelector("#modal-backdrop .avatar");
  const cs = head && getComputedStyle(head);
  return {
    msmatches: matchMedia("(min-width: 720px)").matches,
    headDir: cs?.flexDirection,
    headAlign: cs?.alignItems,
    headTextAlign: cs?.textAlign,
    sheets: [...document.styleSheets].length,
    mediaRules: [...document.styleSheets[0].cssRules].filter((r) => r.media).map((r) => `${r.media.mediaText} -> ${r.cssRules.length} rules`),
    imgClass: img?.className,
    imgRect: img ? Math.round(img.getBoundingClientRect().width) + "x" + Math.round(img.getBoundingClientRect().height) : null,
    imgNatural: img ? img.naturalWidth + "x" + img.naturalHeight : null,
    imgStyleW: img?.style.width,
    imports: [...document.styleSheets].map((s) => (s.href ?? "inline") .split("/").pop()),
  };
});
console.log(JSON.stringify(res, null, 2));
await browser.close();

