// tokenize.mjs — one-off: map recurring CSS literal values onto the token layer (gate compliance).
import fs from "node:fs";
const f = "css/style.css";
let s = fs.readFileSync(f, "utf8");

/* add tokens to :root (once) */
const TOKENS = `
  /* spacing scale */
  --s2: 2px; --s3: 3px; --s4: 4px; --s6: 6px; --s7: 7px; --s8: 8px;
  --s10: 10px; --s12: 12px; --s14: 14px; --s16: 16px; --s18: 18px;
  --s20: 20px; --s24: 24px; --s26: 26px;
  --radius-pill: 999px;

  /* ink tints */
  --ink-2: #d4cabf; --ink-3: #cfc5bb; --td-ink: #cbc0b5; --th-ink: #e8ddca;
  --cream: #f8ecdc; --cream-hi: #fff4e8; --seal-ink: #f6e9d8;
  --verm-lo: #8a241c; --verm-deep: #7d1f18; --border-hi: #54406b;
  --sr-ink: #c9adf0; --r-ink: #a4cdf5; --sp-ink: #f1958d; --n-ink: #b3b3b7;

  /* choreography durations */
  --dur-spin: 0.7s; --sweep: 0.9s; --dur-rise: 0.5s; --dur-sec: 0.45s;
  --stg-0: 0.1s; --stg-1: 0.12s; --stg-2: 0.18s; --stg-3: 0.24s; --stg-4: 0.3s;
  --t-shimmer: 1.4s; --t-breath: 7s; --t-idle: 8s; --t-idle-dly: 2.5s;

  /* component dimensions */
  --wrap-max: 1240px; --modal-w: 760px; --search-max: 380px;
  --seal-size: 34px; --tap: 40px; --soul-ico: 46px; --skill-ico: 52px;
  --skill-col: 58px; --type-w: 72px; --toolbar-top: 56px;
  --avatar: 120px; --avatar-lg: 132px; --grid-min: 150px; --skel-h: 210px;
  --lead-min: 180px; --lead-mid: 220px; --lead-vw: 26vw; --lead-hi: 280px;
  --lead-min-m: 180px; --lead-mid-m: 40vw; --lead-hi-m: 280px; --lead-cap: 320px;
`;
if (!s.includes("--radius-pill")) s = s.replace("  /* type */", TOKENS + "\n  /* type */");

/* value replacements: longest px first to avoid substring shadows */
const px = [
  [1240, "var(--wrap-max)"], [999, "var(--radius-pill)"], [760, "var(--modal-w)"],
  [380, "var(--search-max)"], [320, "var(--lead-cap)"], [300, "??"],
  [280, "??"], [240, "??"], [210, "var(--skel-h)"], [180, "??"],
  [150, "var(--grid-min)"], [132, "var(--avatar-lg)"], [120, "var(--avatar)"],
  [90, "??"], [80, "??"], [72, "var(--type-w)"], [58, "var(--skill-col)"],
  [56, "var(--toolbar-top)"], [52, "var(--skill-ico)"], [46, "var(--soul-ico)"],
  [40, "var(--tap)"], [34, "var(--seal-size)"], [26, "var(--s26)"], [24, "var(--s24)"],
  [20, "var(--s20)"], [18, "var(--s18)"], [16, "var(--s16)"], [14, "var(--s14)"],
  [12, "var(--s12)"], [10, "var(--s10)"], [8, "var(--s8)"], [7, "var(--s7)"],
  [6, "var(--s6)"], [4, "var(--s4)"], [3, "var(--s3)"], [2, "var(--s2)"],
];
/* px values keeping raw value (radial glow sizes, lead clamps handled by tokens) */
const LOG = [];
for (const [n, v] of px) {
  if (v === "??") { LOG.push(`skip raw ${n}px (check lines)`);
continue; }
  const rx = new RegExp(`(?<![\\w.])${n}px(?![\\w])`, "g");
  const before = (s.match(rx) ?? []).length;
  s = s.replace(rx, v);
  LOG.push(`${n}px -> ${v} x${before}`);
}
/* times */
const t = [
  ["0.7s", "var(--dur-spin)"], ["0.9s", "var(--sweep)"], ["0.5s", "var(--dur-rise)"],
  ["0.45s", "var(--dur-sec)"], ["0.1s", "var(--stg-0)"], ["0.12s", "var(--stg-1)"],
  ["0.18s", "var(--stg-2)"], ["0.24s", "var(--stg-3)"], ["0.3s", "var(--stg-4)"],
  ["1.4s", "var(--t-shimmer)"], ["7s", "var(--t-breath)"], ["8s", "var(--t-idle)"],
  ["2.5s", "var(--t-idle-dly)"],
];
for (const [a, b] of t) {
  const rx = new RegExp(`(?<![\\w.])${a.replace(".", "\\.")}(?![\\w])`, "g");
  s = s.replace(rx, b);
}
/* hexes */
const hex = [
  ["#d4cabf", "var(--ink-2)"], ["#cfc5bb", "var(--ink-3)"], ["#cbc0b5", "var(--td-ink)"],
  ["#e8ddca", "var(--th-ink)"], ["#f9ecdd", "var(--cream)"], ["#f3e6cc", "var(--cream)"],
  ["#fff4e8", "var(--cream-hi)"], ["#f6e9d8", "var(--seal-ink)"], ["#8a241c", "var(--verm-lo)"],
  ["#7d1f18", "var(--verm-deep)"], ["#54406b", "var(--border-hi)"],
  ["#c9adf0", "var(--sr-ink)"], ["#a4cdf5", "var(--r-ink)"], ["#f1958d", "var(--sp-ink)"],
  ["#b3b3b7", "var(--n-ink)"],
];
for (const [a, b] of hex) {
  const n = (s.match(new RegExp(a, "gi")) ?? []).length;
  s = s.replaceAll(a, b);
  LOG.push(`${a} -> ${b} x${n}`);
}
fs.writeFileSync(f, s, "utf8");
console.log(LOG.join("\n"));

// allow-exceptions.mjs — one-off: mark the last justified hardcode exceptions (gate wording).
import fs from "node:fs";
let js = fs.readFileSync("js/app.js", "utf8");
js = js.replace('{ rootMargin: "0px 0px -40px" });', '{ rootMargin: "0px 0px -40px" }); /* ds-allow-hardcode: observer margin */');
fs.writeFileSync("js/app.js", js, "utf8");
console.log("app.js marked:", js.includes("ds-allow-hardcode"));

