input.newString:
/* gilded shimmer lane: sweeps on hover; the lead card alone breathes an idle sweep
   (one ambient motion per zone: the hero has its own, the wall stays still) */
.card .sheen {
  position: absolute;
  top: -30%;
  left: -30%;
  width: 60%;
  height: 160%;
  background: linear-gradient(105deg, transparent 40%, var(--sheen) 50%, transparent 60%);
  transform: skewX(-18deg) translateX(-80%);
  opacity: 0;
  pointer-events: none;
}
.card:hover .sheen { animation: sheen-sweep var(--sweep) var(--ease-out); }
.card.lead.in-view .sheen {
  animation: sheen-idle var(--t-idle) var(--ease-in-out) infinite;
  animation-delay: var(--t-idle-dly);
}

