// probe-modal.mjs — one-off: drive modal focus management from the keyboard.
import path from "node:path";
import { createRequire } from "node:module";
const { chromium } = createRequire(path.resolve("ux-ui-agent-skills/package.json"))("playwright");
const browser = await chromium.launch({ channel: "chrome", headless: true });
const page = await (await browser.newContext({ viewport: { width: 1280, height: 900 } })).newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
await page.goto(`http://localhost:8123/shikigami.html?pm=${Date.now()}`, { waitUntil: "networkidle" });
await page.waitForTimeout(600);

const openByKeyboard = await page.evaluate(() => {
  const card = document.querySelector('.card[role="button"]');
  card.focus();
  return document.activeElement === card;
});
await page.keyboard.press("Enter");
await page.waitForTimeout(400);
const afterOpen = await page.evaluate(() => {
  const dlg = document.querySelector(".modal");
  return {
    role: dlg?.getAttribute("role"),
    ariaModal: dlg?.getAttribute("aria-modal"),
    labelledby: dlg?.getAttribute("aria-labelledby") ?? null,
    titleText: dlg?.querySelector("#modal-title")?.textContent ?? null,
    focused: document.activeElement?.className ?? null,
    isCloseBtn: !!document.activeElement?.closest(".close"),
  };
});
// Tab several times: focus must never leave the dialog
const tabCycles = [];
for (let i = 0; i < 6; i++) {
  await page.keyboard.press("Tab");
  tabCycles.push(await page.evaluate(() => !!document.activeElement.closest(".modal")));
}
// Escape: modal closes + restores focus to the opener card
await page.keyboard.press("Escape");
await page.waitForTimeout(200);
const afterClose = await page.evaluate(() => ({
  open: document.querySelector(".modal-backdrop.open") !== null,
  focusedClass: document.activeElement?.className ?? null,
  hash: location.hash,
}));

console.log(JSON.stringify({ openByKeyboard, errors, afterOpen, allTabsInside: tabCycles.every(Boolean), tabCycles, afterClose }, null, 2));
await browser.close();

