// probe-trim.mjs — one-off: inspect alpha/color stats of the 608 art and compare bbox rules.
import path from "node:path";
import { createRequire } from "node:module";
const { chromium } = createRequire(path.resolve("ux-ui-agent-skills/package.json"))("playwright");
const browser = await chromium.launch({ channel: "chrome", headless: true });
const page = await (await browser.newContext({ viewport: { width: 1280, height: 900 } })).newPage();
await page.goto(`http://localhost:8123/shikigami.html?t=${Date.now()}#608`, { waitUntil: "networkidle" });
await page.waitForTimeout(700);
const out = await page.evaluate(async () => {
  const img = document.querySelector(".modal img.avatar.hero");
  if (!img || img.dataset.trimmed === "1") return { state: img?.dataset.trimmed ?? "no img" };
  const c = document.createElement("canvas");
  c.width = img.naturalWidth; c.height = img.naturalHeight;
  const ctx = c.getContext("2d");
  ctx.drawImage(img, 0, 0);
  const { data } = ctx.getImageData(0, 0, c.width, c.height);
  const W = c.width, H = c.height;

  const bboxOf = (rule) => {
    let x0 = W, y0 = H, x1 = 0, y1 = 0, n = 0;
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 4, a = data[i + 3], r = data[i], g = data[i + 1], b = data[i + 2];
      if (rule(a, r, g, b)) { n++; if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
    }
    return n ? `${x1 - x0 + 1}x${y1 - y0 + 1} @(${x0},${y0}) px=${n}` : "none";
  };

  // alpha histogram buckets + corner samples
  const hist = { a0: 0, a1_8: 0, a9_26: 0, a27_60: 0, a61_250: 0, a255: 0, lum0_18_opaque: 0 };
  for (let i = 0; i < data.length; i += 4) {
    const a = data[i + 3], lum = Math.max(data[i], data[i + 1], data[i + 2]);
    if (a === 0) hist.a0++;
    else if (a <= 8) hist.a1_8++;
    else if (a <= 26) hist.a9_26++;
    else if (a <= 60) hist.a27_60++;
    else if (a < 255) hist.a61_250++;
    else { hist.a255++;
      if (lum <= 18) hist.lum0_18_opaque++;
    }
  }
  const px = (x, y) => { const i = (y * W + x) * 4; return `rgba(${data[i]},${data[i + 1]},${data[i + 2]},${data[i + 3]})`; };
  return {
    W, H,
    corners: [px(2, 2), px(30, 2), px(2, 30), px(W - 3, H - 3), px(Math.floor(W / 2), 2)],
    hist,
    bboxAlpha8: bboxOf((a) => a > 8),
    bboxAlpha26: bboxOf((a) => a > 26),
    bboxAlpha60: bboxOf((a) => a > 60),
    bboxVis18: bboxOf((a, r, g, b) => a > 26 && Math.max(r, g, b) > 18),
    bboxVis28: bboxOf((a, r, g, b) => a > 26 && Math.max(r, g, b) > 28),
    bboxVis40: bboxOf((a, r, g, b) => a > 26 && Math.max(r, g, b) > 40),
  };
});
console.log(JSON.stringify(out, null, 1));
await browser.close();

