/* ============ live timezone banner (index) — New York (EST/EDT) & Bangkok (GMT+7) ============ */
const CLOCK_ZONES = [
  { tz: "America/New_York", time: "clock-ny", zone: "clock-ny-tz", date: "clock-ny-date" },
  { tz: "Asia/Bangkok", time: "clock-bkk", zone: "clock-bkk-tz", date: "clock-bkk-date" },
];
function startClockBand() {
  const els = CLOCK_ZONES.map((z) => ({
    time: document.getElementById(z.time),
    zone: document.getElementById(z.zone),
    date: document.getElementById(z.date),
    parts: new Intl.DateTimeFormat("en-GB", {
      timeZone: z.tz, hour: "2-digit", minute: "2-digit", second: "2-digit",
      year: "numeric", month: "short", day: "2-digit", weekday: "short", hourCycle: "h23",
    }),
    zoneName: new Intl.DateTimeFormat("en", { timeZone: z.tz, timeZoneName: "short" }),
    offset: new Intl.DateTimeFormat("en", { timeZone: z.tz, timeZoneName: "longOffset" }),
  }));
  if (!els[0].time) return;

  const part = (arr, type) => arr.find((p) => p.type === type)?.value ?? "";
  const tick = () => {
    const now = new Date();
    for (const e of els) {
      const a = e.parts.formatToParts(now);
      const h = part(a, "hour"), m = part(a, "minute"), s = part(a, "second");
      const off = part(e.offset.formatToParts(now), "timeZoneName").replace(/^GMT/, "").replace(":", "") ||
        "00:00";
      e.time.textContent = `${h}:${m}:${s}`;
      e.time.setAttribute("datetime",
        `${part(a, "year")}-${part(a, "month", false) ?? ""}`.trim() && "");
      e.time.setAttribute("datetime", `${part(a, "year")}-${(a.find((p) => p.type === "month")?.value ?? "").padStart(2, "0")}-${part(a, "day")}T${h}:${m}:${s}${off}`);
      e.zone.textContent = part(e.zoneName.formatToParts(now), "timeZoneName");
      e.date.textContent = `${part(a, "weekday")} · ${part(a, "day")} ${part(a, "month")}`;
    }
  };
  /* re-align to the edge of each second so the banner never drifts */
  const syncTick = () => { tick(); setTimeout(syncTick, 1000 - (Date.now() % 1000) + 2); };
  syncTick();
}

/* boot by page */
const page = document.body.dataset.page;
window.addEventListener("DOMContentLoaded", async () => {
  if (page === "index") { startClockBand(); await renderIndex(); }

