  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.9rem;
  align-items: start;
  padding: 0.85rem 0.7rem;
  border-bottom: 1px solid rgb(var(--gold-rgb) / 0.1);
  background: linear-gradient(165deg, var(--surface-2), var(--surface));
}
.buff-doc:first-child { border-top-left-radius: var(--radius-sm); border-top-right-radius: var(--radius-sm); }
.buff-doc:last-child { border-bottom: none; border-bottom-left-radius: var(--radius-sm); border-bottom-right-radius: var(--radius-sm); }
.buff-doc .cal-ico { margin-top: 0.15rem; }
.buff-doc-body { min-width: 0; }
.buff-name {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--gold-soft);
  font-family: var(--font-latin);
  font-size: 1.02rem;
  letter-spacing: 0.05em;
}
.buff-name .cal-flag { margin-left: auto; }
.buff-doc p {
  margin: 0.25rem 0 0;
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.5;
}
.buff-doc.today { box-shadow: inset 0 0 0 1px rgb(var(--gold-rgb) / 0.4); }
@media (max-width: 620px) {
  .buff-doc { padding: 0.7rem 0.5rem; }
  .buff-doc .cal-ico { width: 26px; height: 26px; }
}

