/* the game's daily-buff rotation, verified against the live server schedule:
   week w + position p map into BUFFS; the position jump (C/D skip week) lands
   after p=3, i.e. the extra +1 applies from p >= 4 */
function buffForDay(day) {
  const w = Math.floor((day - 1) / 7), p = (day - 1) % 7;
  return BUFFS[(w + 5 + p + (p >= 4 ? 1 : 0)) % 7];
}

